mapper.select:
-- Count open batch collection requests for duplicate prevention.
SELECT
    count(1)
FROM announcement_source_collection_requests ascr
WHERE ascr.provider_code = #{providerCode}
  AND ascr.request_type_code = 'BATCH'
  AND ascr.request_status_code = 'APPROVAL_PENDING'
  AND (
      (ascr.search_region_code IS NULL AND #{searchRegionCode} IS NULL)
      OR ascr.search_region_code = #{searchRegionCode}
  )
  AND (
      (ascr.search_category_code IS NULL AND #{searchCategoryCode} IS NULL)
      OR ascr.search_category_code = #{searchCategoryCode}
  )

-- Find exact duplicate source across all other providers.
SELECT 
FROM announcement_source_snapshots ass
WHERE ass.provider_code <> #{providerCode}
  AND (
      (#{canonicalSourceUrl} IS NOT NULL AND ass.canonical_source_url = #{canonicalSourceUrl})
      OR (
          #{postedDate} IS NOT NULL
          AND ass.normalized_title = #{normalizedTitle}
          AND ass.normalized_agency_name = #{normalizedAgencyName}
          AND ass.posted_date = #{postedDate}
      )
  )
ORDER BY ass.collected_at ASC, ass.id ASC
LIMIT 1

mapper.insert:
-- Store cross-provider duplicate pair in canonical UUID order.
INSERT INTO announcement_source_snapshot_duplicates (
    id, source_id, candidate_source_id, match_type_code, title_matched, agency_matched,
    posted_date_matched, source_url_matched, match_reason, decision_status_code
) VALUES (
    #{duplicateId}, LEAST(#{sourceId}, #{candidateSourceId}), GREATEST(#{sourceId}, #{candidateSourceId}),
    #{matchTypeCode}, #{titleMatched}, #{agencyMatched}, #{postedDateMatched}, #{sourceUrlMatched},
    #{matchReason}, #{decisionStatusCode}
)
ON CONFLICT (source_id, candidate_source_id) DO NOTHING
